source("pre.R")
dump <- function(d) .Call(zuhtml:::C_zuh_doc_dump, d$ptr)
rt <- function(h) { d <- html_parse(h); s <- html_serialize(d); d2 <- html_parse(s); ok <- identical(dump(d), dump(d2)); cat(sprintf("%s %-70s => %s\n", if (ok) "ok " else "DIFF", encodeString(h), encodeString(s))); if(!ok) {print(dump(d)); print(dump(d2))} }
