 '<pre>\n\nx</pre>', '<textarea>\n\nx</textarea>', '<listing>\n\nx</listing>','<pre>\nx</pre>','<p>a&#13;b&#0;c&#x80;d</p>', '<select><option>a<optgroup label=x><option>b</select>', '<a href="?a=1&amp;b=2&copy=3&lt=4">x</a>', '<p>&amp;lt; &amp;amp; &amp;nbsp; &#38;#38;</p>', '<div title="&#10;&#9;x">y</div>', '<plaintext><b>x</b>&amp;', '<p><!--a--b--></p><!--->x-->', '<?php echo 1 ?><p>x</p>', '<svg><![CDATA[<b>&amp;]]></svg>', '<svg><p>x</p></svg>', '<table><tr><td>a<b>b<tr><td>c</table>', '<a><table><a>x</a></table></a>', '<b><p>x</b>y</p>', '<form><form><input></form></form>', '<dl><dt>a<dd>b<dt>c</dl>', '<ruby>a<rt>b<rp>c</ruby>', '<button><button>x', '<frameset><frame></frameset>', '<html><head><noscript><link><style>x</style></noscript></head>', '<menuitem>a</menuitem><image src=x>', '<p>  ﻿​</p>', '<math><annotation-xml encoding="application/xhtml+xml"><div>x</div></annotation-xml></math>', '<svg><a xlink:href="x" XLink:Title="t" xml:space="preserve" xmlns:foo="u"/></svg>', '<div xml:lang="en" xlink:href="q">', '<script><!--<script></script>--></script>x', '<script>a</script >b', '<isindex>', '<nobr>a<nobr>b', '<svg><foreignObject><svg><desc><b>x', '<object><param name=a>t</object>', '<details><summary>s</summary>d</details>', '<svg><title>a&amp;b<</title></svg>', '<style><!--</style>-->x', '<title></title><textarea></textarea><textarea>\n</textarea>', '<listing>&#10;x</listing>')) rt(h)
# node-level
d <- html_parse('<div id=d><script>a<b</script><p>x &amp; y</p><template><b>t</b></template><!--c--><br><svg><style>p&gt;q</style></svg></div>')
div <- html_element(d, "#d")
print(html_serialize(div)); print(html_serialize(div, outer=FALSE))
print(html_serialize(html_children(html_element(d,"script"), elements_only=FALSE)))
print(html_serialize(html_children(html_element(d,"svg style"), elements_only=FALSE)))
print(html_serialize(html_element(d,"template"), outer=FALSE)); print(html_serialize(html_template_content(html_element(d,"template"))))
print(html_serialize(html_element(d,"br"))); print(html_serialize(html_element(d,"br"), outer=FALSE))
print(html_serialize(d, outer=FALSE)); print(html_serialize(html_root(d), outer=FALSE))
for (ctx in c("div","script","style","textarea","title","xmp","noscript","plaintext","iframe","tr","select","template","svg","body","html","pre")) { f <- try_(html_fragment("a<b>&amp;</b>&lt;c<td>x</td>\n", context=ctx)); cat(sprintf("%-10s => %s\n", ctx, if (inherits(f,"errstr")) unclass(f) else encodeString(html_serialize(f)))) }
cat(html_serialize(html_parse('<!DOCTYPE html><html><head><title>T</title><meta charset=utf-8><script>var a = 1;\n  b();</script></head><body><div><p>Hello <b>bold</b> <i>it</i></p>foo<script>x</script>bar <span>a<div>blk</div>b</span><pre>  keep\n   <b> me </b></pre><ul><li>one</li> <li>two<ul><li>n</li></ul></li></ul><!--c--><table><tr><td>1</td><td><p>p</p></td></tr></table><textarea> x\n y</textarea><select><option>a</option><option>b</option></select> t <template><p>tp</p> </template></div></body></html>'), pretty=TRUE), "\n")
